// packages/scalyc/0.2.1/scalyc/cli.scaly
__attribute__((weak)) void cli_print_tool_usage()
{
    Console_println(((const char*)"Usage: scaly                            the REPL"));
    Console_println(((const char*)"       scaly run [--gpu] <file> [arguments]   compile and run a program"));
    Console_println(((const char*)"       scaly build <file> [-o <out>] [--release]   build an executable"));
    Console_println(((const char*)"             --pgo-train          ... instrumented: its run writes default.profraw ($LLVM_PROFILE_FILE)"));
    Console_println(((const char*)"             --pgo <profile>      ... optimised with that profile"));
    Console_println(((const char*)"             --export             ... every definition kept and visible: a program that runs others in process"));
    Console_println(((const char*)"             --target <t>, -g, -mcpu=<cpu>, -L<path>, -l<name>   as scalyc takes them"));
    Console_println(((const char*)"       scaly test <file> [filter]       run its test functions"));
    Console_println(((const char*)"       scaly new <name> [--lib]         a directory with a root file: a program, with --lib a package"));
    Console_println(((const char*)"       scaly install <source> <package> <version> [program]   build the programs a package offers (its programs/) from git"));
    Console_println(((const char*)"       scaly install                    what was installed so"));
    Console_println(((const char*)"       scaly uninstall <program>        remove one of them"));
    Console_println(((const char*)"       scaly clean                      empty the cache of compiled packages and interfaces (they are made again when needed)"));
    Console_println(((const char*)"       scaly publish [remote]           record the new versions of the packages here as published, commit and push (origin)"));
    Console_println(((const char*)"       scaly publish --check [remote]   ... only check: no published version changed, each new number says its change"));
    Console_println(((const char*)"       scaly next <package> <version>   begin a package\047s next version: rename its directory, and what names it follows"));
    Console_println(((const char*)""));
    Console_println(((const char*)"The compiler with a command line like a C compiler\047s is scalyc,"));
    Console_println(((const char*)"the language server scalyls."));
}

// packages/scalyc/0.2.1/scalyc/cli.scaly
__attribute__((weak)) void cli_print_usage()
{
    Console_println(((const char*)"Usage: scalyc [options] <input file>"));
    Console_println(((const char*)""));
    Console_println(((const char*)"Options:"));
    Console_println(((const char*)"  -h, --help     Show this help message"));
    Console_println(((const char*)"  -v, --verbose  Verbose output"));
    Console_println(((const char*)"  -o <file>      Output file"));
    Console_println(((const char*)"  -S             Emit LLVM IR"));
    Console_println(((const char*)"  -c             Compile only (no link)"));
    Console_println(((const char*)"  -L<path>       Add library search path"));
    Console_println(((const char*)"  -l<name>       Link library by name"));
    Console_println(((const char*)"  <file>.a/.o    Positional link inputs"));
    Console_println(((const char*)"  --lex          Lex input and print tokens"));
    Console_println(((const char*)"  --parse        Parse input and validate syntax"));
    Console_println(((const char*)"  --model        Build semantic model"));
    Console_println(((const char*)"  --plan         Run planner (type resolution)"));
    Console_println(((const char*)"  --no-prelude   Skip auto-loading prelude module"));
    Console_println(((const char*)"  --no-tests     Omit test/test_* functions (seed build)"));
    Console_println(((const char*)"  --task-plan    Report the parallelizability verdict of every for loop, and every recursive call pair that forks"));
    Console_println(((const char*)"  --loop-census  Report which while loops are counted and could run in parallel"));
    Console_println(((const char*)"  --gpu-plan     Report which parallel for loops a graphics card could run, and for which backends"));
    Console_println(((const char*)"  --gpu-msl      Print the Metal kernel of every parallel for loop a graphics card could run"));
    Console_println(((const char*)"  --gpu-wgsl     Print the WGSL kernel of every parallel for loop a card under WebGPU could run"));
    Console_println(((const char*)"  --pointer-report  Report every raw-pointer site, classified off the Plan"));
    Console_println(((const char*)"  --write-report  Report every write through a parameter, off the Plan"));
    Console_println(((const char*)"  --purity-check  Report every function that writes what its parameters reach"));
    Console_println(((const char*)"  --emit-interface  Write the package\047s interface into the cache, or to -o <dir>"));
    Console_println(((const char*)"  --emit-surface    Write the package\047s declarations alone (what scaly publish compares) to -o <dir>"));
    Console_println(((const char*)"  --run <fn>     JIT-compile and run <fn> in-process"));
    Console_println(((const char*)"  --jit          JIT-compile and run the whole program"));
    Console_println(((const char*)"  --target <t>   Cross-emit object for triple <t> (use with -c)"));
    Console_println(((const char*)"  -mcpu=<cpu>    Generate code for <cpu>, or native for this machine (default generic)"));
    Console_println(((const char*)"  --portable-simd  SIMD operations in their target-neutral form (the seed)"));
    Console_println(((const char*)"  --gpu          Let the program run a parallel for loop on the graphics card where that pays (macOS, and wasm32 in a page that hands it its card; not with --jit or --run; SCALY_GPU=on|off decides for it)"));
}

